def firstArrivalsProofStrip(readings):
    a=readings
    out=[]
    seen=set()
    for x in a:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out


java
class Solution {
  public int[] firstArrivalsProofStrip(int[] readings) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {Set<Integer>seen=new HashSet<>();for(int x:a)if(seen.add(x))out.add(x);}
    return out.stream().mapToInt(Integer::intValue).toArray();
  }
}
